'use strict';
// Configurations are generated by the local server from the accepted getBrandingConfig helper.
// The selector simulates the public flag; it never changes a real environment or app preference.
const REVIEW_BRANDING_KEY='tenops.design-review.branding.v1';
let brandingSaved={};try{brandingSaved=JSON.parse(localStorage.getItem(REVIEW_BRANDING_KEY)||'{}');}catch{}
const brandingQuery=new URLSearchParams(location.search);
const brandingUI={environment:brandingQuery.get('environment')||brandingSaved.environment||'production',appearances:brandingSaved.appearances||{}};
if(!['production','tendev'].includes(brandingUI.environment))brandingUI.environment='production';
function selectedReviewBranding(){return globalThis.TENOPS_REVIEW_BRANDING?.[brandingUI.environment]||null;}
function persistReviewBranding(){try{localStorage.setItem(REVIEW_BRANDING_KEY,JSON.stringify(brandingUI));}catch{}}
function initializeReviewBranding(){const config=selectedReviewBranding();if(config&&state.direction==='b'){const explicit=brandingQuery.get('theme');state.theme=['light','dark'].includes(explicit)?explicit:brandingUI.appearances[brandingUI.environment]||config.defaultAppearance;if(['light','dark'].includes(explicit))brandingUI.appearances[brandingUI.environment]=explicit;persistReviewBranding();}}
function sourceHeaderBranding(unlocked){const config=selectedReviewBranding();if(!config)return '<span class="source-brand-missing" role="alert">Branding configuration unavailable</span>';const dev=config.showDeveloperArtwork,logo=unlocked?config.header.authenticatedLogo:config.header.lockedLogo;const product=unlocked?config.header.authenticatedProductName:config.productName;return `<a class="brand source-brand ${dev?'source-brand-development':''}" href="/" data-nav-href="/" aria-label="Go to Production — ${h(config.productName)}${dev?', Development environment':''}"><img class="source-brand-logo" data-source-brand-asset src="${logo}" alt="Tenarten logo" width="48" height="48"><span class="source-brand-content"><span class="source-product-lockup"><span class="source-brand-product ${dev&&!unlocked?'source-stencil':''}" ${dev&&unlocked?'aria-hidden="true"':''}>${h(product)}</span>${dev&&unlocked?`<img class="source-dev-wordmark" data-source-brand-asset src="${config.header.developmentWordmark}" alt="TenDev" width="1908" height="824">`:''}<span class="source-brand-subtitle ${dev?'source-stencil':''}">${h(config.header.subtitle)}</span></span>${dev&&unlocked?`<span class="source-development-identity"><img data-source-brand-asset src="${config.header.developmentIdentity}" alt="Development Environment" width="1536" height="1024"></span>`:''}</span></a>`;}
function syncReviewBranding(){const select=$('#brand-environment');if(select)select.value=brandingUI.environment;document.body.dataset.reviewEnvironment=brandingUI.environment;const config=state.direction==='b'?selectedReviewBranding():globalThis.TENOPS_REVIEW_BRANDING?.production;if(!config)return;document.title=state.direction==='b'?config.metadata.title:'TenOps · Design review';for(const [id,href] of [['review-favicon',config.metadata.icon192],['review-apple-icon',config.metadata.appleIcon]]){const element=$('#'+id);if(element)element.setAttribute('href',href);}for(const [id,content] of [['review-application-name',config.productName],['review-apple-title',config.productName],['review-theme-color',config.metadata.themeColor]]){const element=$('#'+id);if(element)element.setAttribute('content',content);}}
document.addEventListener('change',event=>{if(event.target.id!=='brand-environment')return;const prior=selectedReviewBranding();if(prior)brandingUI.appearances[brandingUI.environment]=state.theme;brandingUI.environment=event.target.value;const config=selectedReviewBranding();if(config)state.theme=brandingUI.appearances[brandingUI.environment]||config.defaultAppearance;persistReviewBranding();const url=new URL(location.href);url.searchParams.set('environment',brandingUI.environment);history.replaceState(history.state,'',url.pathname+url.search+url.hash);render();});
document.addEventListener('click',event=>{const button=event.target.closest('button');if(button?.id==='theme-toggle'&&state.direction==='b'){brandingUI.appearances[brandingUI.environment]=state.theme==='light'?'dark':'light';persistReviewBranding();}});
document.addEventListener('error',event=>{const asset=event.target;if(!asset.matches?.('[data-source-brand-asset]'))return;const header=asset.closest('.accepted-header');if(!header||header.querySelector('.source-brand-missing'))return;const warning=document.createElement('span');warning.className='source-brand-missing';warning.setAttribute('role','alert');warning.textContent='Missing branding asset: '+asset.getAttribute('src');header.append(warning);},true);
